696	// Registered 按编号排序，Voting 按编号排序；返回的切片与记录均为副本，
697	// 后续执行不会改变已返回的快照，下一次调用重新读取当前已提交状态。
698	func (s *Store) ProposalsSnapshot() (*ProposalsSnapshot, error) {
699		state, err := s.readState()
700		if err != nil {
701			return nil, err
702		}
703		return &ProposalsSnapshot{
704			Registered: proposalRecords(state),
705			Voting:     voteProposalViews(state),
706		}, nil
707	}
