1018	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1019	func quoteAccounts(accounts []string) []string {
1020		quoted := make([]string, len(accounts))
1021		for i, account := range accounts {
1022			quoted[i] = strconv.Quote(account)
1023		}
1024		return quoted
1025	}
