1027	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
1028	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
1029	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
1030	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
1031	// 位置（0 起），与提案编号一起用于定位。
1032	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
1033	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
1034	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
1035		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
1036			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
1037		}
1038		if rcpt.ExecutedAt < timelockEnd {
1039			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
1040				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
1041		}
1042		return nil
1043	}
1044	
1045	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
1046	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
1047	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
1048	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
1049	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
1050	// position 是凭据在凭据表中的位置（0 起）。
1051	func validateReceiptOrder(position int, rcpt *Receipt) error {
1052		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1053			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1054				position, rcpt.ProposalID, "order", problem)
1055		}
1056		if rcpt.Order != int64(position) {
1057			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1058				position, rcpt.ProposalID, "order", rcpt.Order, position)
1059		}
1060		return nil
1061	}
1062	
1063	// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
1064	// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
1065	// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
1066	// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
1067	// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
1068	// 动作在凭据 actions 中的位置（0 起）。
1069	func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
1070		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1071			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1072				id, position, "index", problem)
1073		}
1074		if ar.Index != int64(position) {
1075			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1076				id, position, "index", ar.Index, position)
1077		}
1078		return nil
1079	}
