1081	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1082	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1083	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1084	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1085	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1086	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1087	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1088	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1089	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1090		sides := []struct {
1091			name   string
1092			update *BalanceUpdate
1093		}{
1094			{"treasury", &ar.Treasury},
1095			{"recipient", &ar.Recipient},
1096		}
1097		for _, side := range sides {
1098			err := validateRawFields([]rawField{
1099				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1100				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1101			}, func(field, problem string) error {
1102				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1103					id, index, side.name, field, problem)
1104			})
1105			if err != nil {
1106				return err
1107			}
1108		}
1109		return nil
1110	}
