1112	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1113	
1114	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1115	type schemaKind int
1116	
1117	const (
1118		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1119		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1120		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1121		kindArray                     // 数组
1122		kindString                    // 叶子：必须是 JSON 字符串
1123		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1124		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1125	)
1126	
1127	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1128	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1129	type schemaNode struct {
1130		kind   schemaKind
1131		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1132		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1133	}
1134	
1135	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1136	func schemaOf(t reflect.Type) *schemaNode {
1137		for t.Kind() == reflect.Pointer {
1138			t = t.Elem()
1139		}
1140		switch t.Kind() {
1141		case reflect.Struct:
1142			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1143			for i := 0; i < t.NumField(); i++ {
1144				f := t.Field(i)
1145				if f.PkgPath != "" { // 未导出字段不参与 JSON
1146					continue
1147				}
1148				name := f.Name
1149				if tag, ok := f.Tag.Lookup("json"); ok {
1150					tagName, _, _ := strings.Cut(tag, ",")
1151					if tagName == "-" {
1152						continue
1153					}
1154					if tagName != "" {
1155						name = tagName
1156					}
1157				}
1158				node.fields[name] = schemaOf(f.Type)
1159			}
1160			return node
1161		case reflect.Map:
1162			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1163		case reflect.Slice, reflect.Array:
1164			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1165		case reflect.String:
1166			return &schemaNode{kind: kindString}
1167		case reflect.Bool:
1168			return &schemaNode{kind: kindBoolean}
1169		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1170			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1171			return &schemaNode{kind: kindInteger}
1172		default:
1173			return &schemaNode{kind: kindAny}
1174		}
1175	}
