1177	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1178	
1179	func init() {
1180		// 票据的四个标量字段（representative/weight/support/voted_at）由
1181		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1182		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1183		// 不抢在解码器之前用不含票据定位的通用信息报错。
1184		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1185		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1186			ballotFields[name].kind = kindAny
1187		}
1188		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1189		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1190		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1191		// 其“不早于截止”的既有校验不变。
1192		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1193		for _, name := range []string{"for_weight", "against_weight"} {
1194			tallyFields[name].kind = kindAny
1195		}
1196		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1197		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1198		// 叶子位置保持宽松。
1199		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1200		receiptFields["executed_at"].kind = kindAny
1201		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1202		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1203		receiptFields["order"].kind = kindAny
1204		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1205		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1206		// 此叶子位置保持宽松。
1207		receiptFields["actions"].elem.fields["index"].kind = kindAny
1208		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1209		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1210		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1211		actionFields := receiptFields["actions"].elem.fields
1212		for _, side := range []string{"treasury", "recipient"} {
1213			balanceFields := actionFields[side].fields
1214			balanceFields["before"].kind = kindAny
1215			balanceFields["after"].kind = kindAny
1216		}
1217	}
