1219	// scanFrame 是结构扫描的栈帧。
1220	type scanFrame struct {
1221		node    *schemaNode
1222		isArray bool
1223		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1224		seen    map[string]bool
1225		atValue bool // 对象帧：下一个待消费 token 是值而非键
1226		index   int  // 数组帧：下一个元素下标
1227		path    string
1228	}
1229	
1230	func peekFrame(stack []*scanFrame) *scanFrame {
1231		if len(stack) == 0 {
1232			return nil
1233		}
1234		return stack[len(stack)-1]
1235	}
1236	
1237	// checkStateStructure 在解码前逐 token 扫描状态文件：
1238	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1239	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1240	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1241	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1242	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1243	//
1244	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1245	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1246	func checkStateStructure(raw []byte) error {
1247		dec := json.NewDecoder(bytes.NewReader(raw))
1248		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1249		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1250		dec.UseNumber()
1251		var stack []*scanFrame
1252		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1253		pendingNode := storedStateSchema
1254		pendingPath := "state"
1255	
1256		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1257		finishValue := func() {
1258			top := peekFrame(stack)
1259			if top == nil || top.opaque {
1260				return
1261			}
1262			if top.isArray {
1263				top.index++
1264			} else {
1265				top.atValue = false
1266			}
1267		}
1268	
1269		for {
1270			tok, err := dec.Token()
1271			if err == io.EOF {
1272				if len(stack) != 0 {
1273					return errors.New("unterminated object or array")
1274				}
1275				return nil
1276			}
1277			if err != nil {
1278				return err
1279			}
1280	
1281			if top := peekFrame(stack); top != nil && top.opaque {
1282				// 不透明容器内不做字段检查，只配对括号。
1283				if d, ok := tok.(json.Delim); ok {
1284					if d == '{' || d == '[' {
1285						stack = append(stack, &scanFrame{opaque: true})
1286					} else {
1287						stack = stack[:len(stack)-1]
1288						finishValue()
1289					}
1290				}
1291				continue
1292			}
1293	
1294			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1295				// 对象帧的键位置：闭括号或下一个键。
1296				if d, ok := tok.(json.Delim); ok {
1297					if d != '}' {
1298						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1299					}
1300					stack = stack[:len(stack)-1]
1301					finishValue()
1302					continue
1303				}
1304				key, ok := tok.(string)
1305				if !ok {
1306					return errors.New("object key must be a string")
1307				}
1308				if top.seen[key] {
1309					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1310				}
1311				top.seen[key] = true
1312				top.atValue = true
1313				switch top.node.kind {
1314				case kindObject:
1315					child, known := top.node.fields[key]
1316					if !known {
1317						return fmt.Errorf("unknown field %q at %s", key, top.path)
1318					}
1319					pendingNode = child
1320					pendingPath = top.path + "." + key
1321				case kindMap:
1322					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1323					pendingNode = top.node.elem
1324					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1325				}
1326				continue
1327			}
1328	
1329			// 值位置：对象键之后的值或数组元素。
1330			node := pendingNode
1331			path := pendingPath
1332			if top := peekFrame(stack); top != nil && top.isArray {
1333				node = top.node.elem
1334				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1335			}
1336			if d, ok := tok.(json.Delim); ok {
1337				switch d {
1338				case '{', '[':
1339					frame := &scanFrame{isArray: d == '[', path: path}
1340					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1341						(d == '[' && node.kind == kindArray)
1342					if !shapeOK {
1343						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1344						frame.opaque = true
1345					} else {
1346						frame.node = node
1347						if d == '{' {
1348							frame.seen = map[string]bool{}
1349						}
1350					}
1351					stack = append(stack, frame)
1352				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1353					if len(stack) == 0 {
1354						return errors.New("unexpected closing delimiter")
1355					}
1356					stack = stack[:len(stack)-1]
1357					finishValue()
1358				}
1359				continue
1360			}
1361			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1362			// null 不允许用来顶替字符串/布尔/整数。
1363			if err := checkLeafScalar(node, path, tok); err != nil {
1364				return err
1365			}
1366			finishValue()
1367		}
1368	}
1369	
1370	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1371	func leafKindName(k schemaKind) string {
1372		switch k {
1373		case kindString:
1374			return "string"
1375		case kindBoolean:
1376			return "boolean"
1377		case kindInteger:
1378			return "integer"
1379		default:
1380			return "value"
1381		}
1382	}
1383	
1384	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1385	func tokenKindName(tok json.Token) string {
1386		switch v := tok.(type) {
1387		case nil:
1388			return "null"
1389		case string:
1390			return "string"
1391		case bool:
1392			return "boolean"
1393		case json.Number:
1394			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1395				return "integer"
1396			}
1397			return "number"
1398		default:
1399			return "value"
1400		}
1401	}
1402	
1403	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1404	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1405	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1406		switch node.kind {
1407		case kindString, kindBoolean, kindInteger:
1408		default:
1409			return nil
1410		}
1411		if node.kind == kindInteger {
1412			if n, ok := tok.(json.Number); ok {
1413				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1414					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1415				}
1416				return nil
1417			}
1418		}
1419		want := leafKindName(node.kind)
1420		if got := tokenKindName(tok); got != want {
1421			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1422		}
1423		return nil
1424	}
1425

