62	func usage() {
63		fmt.Println(`usage: govflow <command> [flags]
64	
65	legacy commands:
66	  demo                         run the built-in voting demo
67	  version                      print the version
68	
69	local treasury commands:
70	  init       --state FILE --balance N
71	             create a new state file with the initial treasury balance
72	  register   --state FILE --id ID --timelock N --action A [--action A ...]
73	             register a passed proposal (idempotent; conflicting content errors)
74	  create-vote --state FILE --id ID --member ID:W [--member ID:W ...]
75	             [--delegate FROM:TO ...] --quorum N --start N --deadline N
76	             --timelock N [--action A ...]
77	             create a voting proposal with roster, weights, delegations and a
78	             voting window (idempotent on identical content; conflict otherwise)
79	  vote       --state FILE --id ID --voter M --choice for|against --now N
80	             cast one ballot as a final representative (repeat same choice is
81	             idempotent; changing choice errors)
82	  tally      --state FILE --id ID --now N
83	             tally a proposal at/after its deadline; repeat calls return the
84	             first result
85	  execute    --state FILE --id ID --now N
86	             execute a passed proposal whose timelock has elapsed
87	             (works for both registered and voted proposals)
88	  balances   --state FILE [--account ACCT]
89	             show treasury and recipient account balances
90	  proposal   --state FILE --id ID
91	             show one registered proposal
92	  proposals  --state FILE
93	             list all registered proposals by id
94	  receipt    --state FILE --id ID
95	             show the execution receipt of one proposal
96	  receipts   --state FILE
97	             list all receipts in the order they were successfully committed
98	
99	all treasury commands accept --json for machine-readable output.`)
100	}
101	
102	// fail prints a domain error to stderr and exits 1; usage errors exit 2.
103	func fail(err error) {
104		fmt.Fprintf(os.Stderr, "error: %v\n", err)
105		os.Exit(1)
106	}
107	
108	type commonFlags struct {
109		state  string
110		asJSON bool
111		fs     *flag.FlagSet
112	}
113	
114	func newCmdFlags(name string) *commonFlags {
115		fs := flag.NewFlagSet(name, flag.ContinueOnError)
116		fs.SetOutput(io.Discard)
117		cf := &commonFlags{fs: fs}
118		fs.StringVar(&cf.state, "state", "", "path to the local treasury state file")
119		fs.BoolVar(&cf.asJSON, "json", false, "emit machine-readable JSON")
120		return cf
121	}
122	
123	func (c *commonFlags) parse(args []string) {
124		if err := c.fs.Parse(args); err != nil {
125			fmt.Fprintf(os.Stderr, "usage error: %v\n", err)
126			c.fs.SetOutput(os.Stderr)
127			c.fs.Usage()
128			os.Exit(2)
129		}
130		if c.state == "" {
131			fmt.Fprintf(os.Stderr, "usage error: --state is required\n")
132			os.Exit(2)
133		}
134	}
135	
136	func emitJSON(v any) {
137		raw, err := json.MarshalIndent(v, "", "  ")
138		if err != nil {
139			fail(err)
140		}
141		fmt.Println(string(raw))
142	}
143	
144	func parseIntFlag(fs *flag.FlagSet, name, raw string) int64 {
145		if raw == "" {
146			fmt.Fprintf(os.Stderr, "usage error: --%s is required\n", name)
147			os.Exit(2)
148		}
149		value, err := strconv.ParseInt(raw, 10, 64)
150		if err != nil {
151			fmt.Fprintf(os.Stderr, "usage error: --%s must be an int64: %v\n", name, err)
152			os.Exit(2)
153		}
154		return value
155	}
156	
157	// actionList 收集重复出现的 --action 参数，保持登记顺序。
158	type actionList []string
159	
160	func (a *actionList) String() string { return fmt.Sprint([]string(*a)) }
161	func (a *actionList) Set(v string) error {
162		*a = append(*a, v)
163		return nil
164	}
165	
166	func runInit(args []string) {
167		cf := newCmdFlags("init")
168		balanceRaw := cf.fs.String("balance", "", "initial treasury balance (non-negative int64)")
169		cf.parse(args)
170		balance := parseIntFlag(cf.fs, "balance", *balanceRaw)
171	
172		store, err := govflow.InitTreasury(cf.state, balance)
173		if err != nil {
174			fail(err)
175		}
176		defer store.Close()
177		if cf.asJSON {
178			emitJSON(map[string]any{"state": cf.state, "treasury": balance, "initialized": true})
179			return
180		}
181		fmt.Printf("initialized %s with treasury balance %d\n", cf.state, balance)
182	}
183	
184	func runRegister(args []string) {
185		cf := newCmdFlags("register")
186		id := cf.fs.String("id", "", "proposal id (non-empty)")
187		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
188		var actions actionList
189		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
190		cf.parse(args)
191		if *id == "" {
192			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
193			os.Exit(2)
194		}
195		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
196	
197		store, err := govflow.Open(cf.state)
198		if err != nil {
199			fail(err)
200		}
201		defer store.Close()
202		existed, err := store.Register(*id, timelock, []string(actions))
203		if err != nil {
204			fail(err)
205		}
206		if cf.asJSON {
207			emitJSON(map[string]any{"id": *id, "state": "passed", "timelock_end": timelock,
208				"actions": []string(actions), "already_registered": existed})
209			return
210		}
211		if existed {
212			fmt.Printf("proposal %s already registered with identical content\n", *id)
213		} else {
214			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", *id, len(actions), timelock)
215		}
216	}
217	
218	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
219	type memberList []govflow.VoteMember
220	
221	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
222	func (m *memberList) Set(v string) error {
223		id, weight, err := splitMember(v)
224		if err != nil {
225			return err
226		}
227		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
228		return nil
229	}
230	
231	func splitMember(raw string) (string, int64, error) {
232		idx := strings.LastIndex(raw, ":")
233		if idx <= 0 || idx == len(raw)-1 {
234			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
235		}
236		id := raw[:idx]
237		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
238		if err != nil {
239			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
240		}
241		return id, weight, nil
242	}
243	
244	// delegationList 收集重复的 --delegate FROM:TO 参数原文，保持提交顺序。
245	// 成员编号本身可含冒号（如 team:alice），FROM 与 TO 两端都可能含冒号，
246	// 因此不能在解析单个参数时切分：必须等完整成员名单齐备后，
247	// 由 resolveDelegations 结合名单确定唯一的切分点。
248	type delegationList []string
249	
250	func (d *delegationList) String() string { return fmt.Sprint([]string(*d)) }
251	func (d *delegationList) Set(v string) error {
252		*d = append(*d, v)
253		return nil
254	}
255	
256	// delegationUsageError 是 --delegate 的参数错误（格式错误或切分有歧义），
257	// 以退出码 2 结束；格式正确但无法匹配名单的错误不属于此类，按域错误退出码 1 处理。
258	type delegationUsageError struct{ reason string }
259	
260	func (e *delegationUsageError) Error() string { return e.reason }
261	
262	// resolveDelegations 结合本次提交的完整成员名单理解每条 FROM:TO 委托原文。
263	// 成员编号保持原文并区分大小写；编号可含冒号，且冒号可以出现在编号开头、
264	// 末尾或连续出现（如 ":alice"、"a:"、"a::b"），所以一条委托原文在每个冒号
265	// 位置都有一种候选切分，切分点两侧的编号仍须各自非空。
266	//
267	// 判定只依据“两端非空”这一纯语法条件与成员名单，不拿自委托/重复/循环等
268	// 业务规则替用户筛选候选：
269	//   - 原文不含冒号，或每个冒号位置的切分都会让某一端为空（如 ":alice"、
270	//     "alice:"、":"、"::"：冒号只出现在首尾、中间再无切分点）：格式错误，
271	//     参数错误（退出码 2）；
272	//   - 存在两端非空的切分，但没有任何一对都在名单里：域错误（退出码 1）；
273	//   - 两对或更多成员同时命中（即使其中某种解释随后会触发自委托、重复或循环）：
274	//     委托有歧义，参数错误（退出码 2），错误列出有歧义的原文与全部成员对；
275	//   - 恰好一对命中：按该对成员创建委托。
276	//
277	// 成员与委托参数在命令行上的排列先后不影响结果：解析前名单已收集完毕。
278	func resolveDelegations(members []govflow.VoteMember, raws []string) ([]govflow.Delegation, error) {
279		roster := make(map[string]bool, len(members))
280		for _, m := range members {
281			roster[m.ID] = true
282		}
283		out := make([]govflow.Delegation, 0, len(raws))
284		for _, raw := range raws {
285			var matches []govflow.Delegation
286			hasNonEmptySplit := false
287			for i := 0; i < len(raw); i++ {
288				if raw[i] != ':' {
289					continue
290				}
291				from, to := raw[:i], raw[i+1:]
292				// 纯语法候选：切分点两侧都非空才算“存在 FROM:TO 写法”。
293				// 编号本身允许以冒号开头、结尾或包含连续冒号，因此位于位置 0
294				// 的冒号产生的空 from、以及结尾冒号产生的空 to 都只是不合法的
295				// 切分点之一，绝不据此提前拒绝整条原文——其他冒号位置仍可能合法。
296				if from == "" || to == "" {
297					continue
298				}
299				hasNonEmptySplit = true
300				if roster[from] && roster[to] {
301					matches = append(matches, govflow.Delegation{From: from, To: to})
302				}
303			}
304			if !hasNonEmptySplit {
305				return nil, &delegationUsageError{fmt.Sprintf("malformed delegation %q, expected FROM:TO with non-empty member ids on both sides", raw)}
306			}
307			switch len(matches) {
308			case 0:
309				return nil, fmt.Errorf("delegation %q does not match any pair of members on the roster", raw)
310			case 1:
311				out = append(out, matches[0])
312			default:
313				pairs := make([]string, len(matches))
314				for i, m := range matches {
315					pairs[i] = fmt.Sprintf("%q delegating to %q", m.From, m.To)
316				}
317				return nil, &delegationUsageError{fmt.Sprintf("ambiguous delegation %q: could mean %s",
318					raw, strings.Join(pairs, " or "))}
319			}
320		}
321		return out, nil
322	}
323	
324	func runCreateVote(args []string) {
325		cf := newCmdFlags("create-vote")
326		id := cf.fs.String("id", "", "proposal id (non-empty)")
327		var members memberList
328		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
329		var delegationRaws delegationList
330		cf.fs.Var(&delegationRaws, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality; either side may itself contain colons and is matched against the full member roster)")
331		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
332		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
333		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
334		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
335		var actions actionList
336		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
337		cf.parse(args)
338		if *id == "" {
339			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
340			os.Exit(2)
341		}
342		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
343		start := parseIntFlag(cf.fs, "start", *startRaw)
344		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
345		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
346		if len(members) == 0 {
347			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
348			os.Exit(2)
349		}
350		// 委托切分依赖完整成员名单，必须在打开状态文件之前完成：
351		// 格式错误与歧义是参数错误（退出码 2），无法匹配名单是域错误（退出码 1），
352		// 两种失败都不触碰已有状态文件。
353		delegations, derr := resolveDelegations([]govflow.VoteMember(members), []string(delegationRaws))
354		if derr != nil {
355			var usageErr *delegationUsageError
356			if errors.As(derr, &usageErr) {
357				fmt.Fprintf(os.Stderr, "usage error: %v\n", derr)
358				os.Exit(2)
359			}
360			fail(derr)
361		}
362	
363		store, err := govflow.Open(cf.state)
364		if err != nil {
365			fail(err)
366		}
367		defer store.Close()
368		in := &govflow.CreateVoteInput{
369			ID:          *id,
370			Members:     []govflow.VoteMember(members),
371			Delegations: delegations,
372			Quorum:      quorum,
373			StartAt:     start,
374			Deadline:    deadline,
375			TimelockEnd: timelock,
376			Actions:     []string(actions),
377		}
378		view, existed, err := store.CreateVoteProposal(in)
379		if err != nil {
380			fail(err)
381		}
382		if cf.asJSON {
383			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
384			return
385		}
386		if existed {
387			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
388		} else {
389			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
390				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
391		}
392	}
393	
394	func runVote(args []string) {
395		cf := newCmdFlags("vote")
396		id := cf.fs.String("id", "", "proposal id to vote on")
397		voter := cf.fs.String("voter", "", "voting member (must be a final representative)")
398		choice := cf.fs.String("choice", "", "vote choice: for or against")
399		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64)")
400		cf.parse(args)
401		if *id == "" || *voter == "" {
402			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
403			os.Exit(2)
404		}
405		var support bool
406		switch *choice {
407		case "for":
408			support = true
409		case "against":
410			support = false
411		default:
412			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
413			os.Exit(2)
414		}
415		now := parseIntFlag(cf.fs, "now", *nowRaw)
416	
417		store, err := govflow.Open(cf.state)
418		if err != nil {
419			fail(err)
420		}
421		defer store.Close()
422		ballot, err := store.CastVote(*id, *voter, support, now)
423		if err != nil {
424			fail(err)
425		}
426		if cf.asJSON {
427			emitJSON(ballot)
428			return
429		}
430		fmt.Printf("recorded vote proposal=%s representative=%s choice=%s weight=%d voted_at=%d\n",
431			*id, ballot.Representative, choiceWord(ballot.Support), ballot.Weight, ballot.VotedAt)
432	}
433	
434	func choiceWord(support bool) string {
435		if support {
436			return "for"
437		}
438		return "against"
439	}
440	
441	func runTally(args []string) {
442		cf := newCmdFlags("tally")
443		id := cf.fs.String("id", "", "proposal id to tally")
444		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64, >= deadline)")
445		cf.parse(args)
446		if *id == "" {
447			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
448			os.Exit(2)
449		}
450		now := parseIntFlag(cf.fs, "now", *nowRaw)
451	
452		store, err := govflow.Open(cf.state)
453		if err != nil {
454			fail(err)
455		}
456		defer store.Close()
457		result, err := store.TallyVote(*id, now)
458		if err != nil {
459			fail(err)
460		}
461		if cf.asJSON {
462			emitJSON(map[string]any{"id": *id, "result": result})
463			return
464		}
465		verdict := "rejected"
466		if result.Passed {
467			verdict = "passed"
468		}
469		fmt.Printf("tally proposal=%s for=%d against=%d turnout=%d quorum=%d => %s (tallied_at=%d)\n",
470			*id, result.ForWeight, result.AgainstWeight, result.Turnout, result.Quorum, verdict, result.TalliedAt)
471	}
