1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"sort"
8	)
9	
10	// 投票提案相关错误。
11	var (
12		// ErrInvalidProposal：创建投票提案的参数非法（编号/成员/权重/时间/委托等）。
13		ErrInvalidProposal = errors.New("invalid voting proposal")
14		// ErrProposalNotFound 见 store.go。
15		// ErrProposalConflict：同编号提案已存在但内容或来源不同，或重复投票选择不同。
16		// ErrVoteRejected：投票被拒绝（时间窗口外、投票人无资格等）。
17		ErrVoteRejected = errors.New("vote rejected")
18		// ErrTallyRejected：计票被拒绝（截止时刻未到）。
19		ErrTallyRejected = errors.New("tally rejected")
20	)
21	
22	// ---- 输入与对外视图 ----
23	
24	// VoteMember 是创建投票提案时提交的一名成员及其原始权重。
25	type VoteMember struct {
26		ID     string `json:"id"`
27		Weight int64  `json:"weight"`
28	}
29	
30	// Delegation 表示 From 把投票权委托给 To。委托可以继续转交，
31	// 最终未再委托的人代表沿途所有成员投票。
32	type Delegation struct {
33		From string `json:"from"`
34		To   string `json:"to"`
35	}
36	
37	// CreateVoteInput 是创建一项投票提案的完整输入。
38	type CreateVoteInput struct {
39		ID          string
40		Members     []VoteMember
41		Delegations []Delegation
42		Quorum      int64
43		StartAt     int64
44		Deadline    int64
45		TimelockEnd int64
46		Actions     []string
47	}
48	
49	// MemberView 是查询时展示的一名成员：委托路径、最终代表与原始权重。
50	type MemberView struct {
51		ID       string   `json:"id"`
52		Weight   int64    `json:"weight"`
53		Path     []string `json:"path"`      // 从本人到最终代表的完整编号链（含首尾）
54		Delegate string   `json:"delegate"`  // 最终代表
55		Direct   string   `json:"direct_to"` // 直接委托对象；未委托为空串
56	}
57	
58	// BallotView 是查询时展示的一张已投出的票。
59	type BallotView struct {
60		Representative string `json:"representative"`
61		Weight         int64  `json:"weight"`
62		Support        bool   `json:"support"`
63		VotedAt        int64  `json:"voted_at"`
64	}
65	
66	// TallyResultView 是首次计票结论的查询视图；尚未计票时为 nil。
67	type TallyResultView struct {
68		ForWeight     int64 `json:"for_weight"`
69		AgainstWeight int64 `json:"against_weight"`
70		Turnout       int64 `json:"turnout"`
71		Quorum        int64 `json:"quorum"`
72		Passed        bool  `json:"passed"`
73		TalliedAt     int64 `json:"tallied_at"`
74	}
75	
76	// VoteProposalView 是一项投票提案的完整对外视图。
77	type VoteProposalView struct {
78		ID          string           `json:"id"`
79		Source      string           `json:"source"` // vote
80		State       string           `json:"state"`  // voting / passed / rejected / executed
81		Quorum      int64            `json:"quorum"`
82		StartAt     int64            `json:"start_at"`
83		Deadline    int64            `json:"deadline"`
84		TimelockEnd int64            `json:"timelock_end"`
85		Actions     []string         `json:"actions"`
86		TotalWeight int64            `json:"total_weight"`
87		Members     []MemberView     `json:"members"`
88		Ballots     []BallotView     `json:"ballots"`
89		Tally       *TallyResultView `json:"tally,omitempty"`
90	}
91	
92	// ---- 磁盘结构（JSON，版本仍为 1） ----
93	
94	type storedMember struct {
95		ID     string `json:"id"`
96		Weight int64  `json:"weight"`
97	}
98	
99	type storedDelegation struct {
100		From string `json:"from"`
101		To   string `json:"to"`
102	}
103	
104	// storedBallot 是一张已保存的票。四个字段都必须明确写出、非空且类型正确：
105	// representative 是 JSON 字符串，weight/voted_at 是 JSON 整数（int64 范围），
106	// support 必须是 JSON 布尔值。绝不能靠零值/默认值补出治理记录：
107	// 缺失或 null 的 support 不得被当作 false（反对票），缺失或 null 的
108	// voted_at 不得被当作 0（首次投票时间）。
109	//
110	// 标量字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
111	// 仍可区分：encoding/json 直接解进 bool/int64/string 时会把这三种情况都
112	// 折叠成零值。每个字段的“缺失/空值/类型不符”由 validateStoredBallot 判定。
113	type storedBallot struct {
114		Representative string `json:"representative"`
115		Weight         int64  `json:"weight"`
116		Support        bool   `json:"support"`
117		VotedAt        int64  `json:"voted_at"`
118	
119		representativeRaw json.RawMessage
120		weightRaw         json.RawMessage
121		supportRaw        json.RawMessage
122		votedAtRaw        json.RawMessage
123	}
124	
125	// ballotJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
126	type ballotJSONShape struct {
127		Representative json.RawMessage `json:"representative"`
128		Weight         json.RawMessage `json:"weight"`
129		Support        json.RawMessage `json:"support"`
130		VotedAt        json.RawMessage `json:"voted_at"`
131	}
132	
133	// UnmarshalJSON 保留字段是否出现及其原始写法（缺失为 nil、null 为 "null"），
134	// 供 validateStoredBallot 区分缺失、空值与类型不符。单个字段类型不符时这里
135	// 不返回错误（对应治理字段保持零值），以免解码器在不含提案编号/票据下标的
136	// 通用错误处提前失败；定位与判定统一交给 validateStoredBallot。
137	func (b *storedBallot) UnmarshalJSON(data []byte) error {
138		var shape ballotJSONShape
139		if err := json.Unmarshal(data, &shape); err != nil {
140			return err
141		}
142		b.representativeRaw, b.weightRaw = shape.Representative, shape.Weight
143		b.supportRaw, b.votedAtRaw = shape.Support, shape.VotedAt
144		// 仅当字段确实是目标类型时才填充治理字段；类型不符留待校验拒绝，
145		// 绝不能让错误类型悄悄落成零值并参与查询或计票。
146		fillString(shape.Representative, &b.Representative)
147		fillInt64(shape.Weight, &b.Weight)
148		fillBool(shape.Support, &b.Support)
149		fillInt64(shape.VotedAt, &b.VotedAt)
150		return nil
151	}
152	
153	// MarshalJSON 只输出四个治理字段，RawMessage 状态（仅用于入站判定）不落盘。
154	func (b storedBallot) MarshalJSON() ([]byte, error) {
155		return json.Marshal(storedBallotOut{
156			Representative: b.Representative,
157			Weight:         b.Weight,
158			Support:        b.Support,
159			VotedAt:        b.VotedAt,
160		})
161	}
162	
163	// storedBallotOut 是票据的保存形状；字段名与保存格式逐字一致。
164	type storedBallotOut struct {
165		Representative string `json:"representative"`
166		Weight         int64  `json:"weight"`
167		Support        bool   `json:"support"`
168		VotedAt        int64  `json:"voted_at"`
169	}
