191	// validateStoredBallot 严格判定一张已保存票据的四个必填字段：
192	// 任一字段未写出、显式为 null 或 JSON 类型不符（support 不接受字符串/数字，
193	// weight/voted_at 不接受字符串/小数/指数等非整数）都返回带原因的错误。
194	// 明确写出的 false 是有效反对票；窗口允许时明确写出的 0 是有效投票时间，
195	// 这两种合法值不得当成缺失。index 是票据在提案中的下标（0 起），用于定位。
196	// “缺失/空值/类型不符”的判定与计票结果、执行凭据共用同一份规则
197	// （validateRawFields），此处只补充票据的业务位置：提案编号 + 票据下标。
198	func validateStoredBallot(id string, index int, b *storedBallot) error {
199		return validateRawFields([]rawField{
200			{name: "representative", kind: scalarString, raw: b.representativeRaw},
201			{name: "weight", kind: scalarInteger, raw: b.weightRaw},
202			{name: "support", kind: scalarBoolean, raw: b.supportRaw},
203			{name: "voted_at", kind: scalarInteger, raw: b.votedAtRaw},
204		}, func(field, problem string) error {
205			return fmt.Errorf("voting proposal %q ballot %d field %q %s", id, index, field, problem)
206		})
207	}
208	
209	// storedTally 是已保存的首次计票结果。只要提案有计票结果，for_weight 与
210	// against_weight 就必须各自明确写出：即使某一侧（或两侧）的实际票重为零，
211	// 也不得靠零值/默认值补出治理记录——缺失或 null 的 for_weight 不得被当作 0
212	// 赞成，缺失或 null 的 against_weight 不得被当作 0 反对。
213	//
214	// 两个权重字段先用 RawMessage 接住，使“字段缺失”与“显式 null/写错类型”在解码后
215	// 仍可区分：encoding/json 直接解进 int64 时会把这三种情况都折叠成 0，恰好与
216	// “该侧没有票”的合法零权重无法区分。每个字段的“缺失/空值/类型不符”由
217	// validateStoredTally 判定。
218	type storedTally struct {
219		ForWeight     int64 `json:"for_weight"`
220		AgainstWeight int64 `json:"against_weight"`
221		TalliedAt     int64 `json:"tallied_at"`
222	
223		forWeightRaw     json.RawMessage
224		againstWeightRaw json.RawMessage
225	}
226	
227	// tallyJSONShape 只用于解码，按保存格式的字段名逐字接住每个字段的原始 JSON。
228	type tallyJSONShape struct {
229		ForWeight     json.RawMessage `json:"for_weight"`
230		AgainstWeight json.RawMessage `json:"against_weight"`
231		TalliedAt     int64           `json:"tallied_at"`
232	}
233	
234	// UnmarshalJSON 保留两个权重字段是否出现及其原始写法（缺失为 nil、null 为
235	// "null"），供 validateStoredTally 区分缺失、空值与类型不符。单个字段类型不符时
236	// 这里不返回错误（对应治理字段保持零值），以免解码器在不含提案编号的通用错误处
237	// 提前失败；定位与判定统一交给 validateStoredTally。
238	func (t *storedTally) UnmarshalJSON(data []byte) error {
239		var shape tallyJSONShape
240		if err := json.Unmarshal(data, &shape); err != nil {
241			return err
242		}
243		t.forWeightRaw, t.againstWeightRaw = shape.ForWeight, shape.AgainstWeight
244		t.TalliedAt = shape.TalliedAt
245		// 仅当字段确实是 int64 整数时才填充治理字段；类型不符留待校验拒绝，
246		// 绝不能让错误类型悄悄落成 0 并参与查询或再次计票。
247		fillInt64(shape.ForWeight, &t.ForWeight)
248		fillInt64(shape.AgainstWeight, &t.AgainstWeight)
249		return nil
250	}
