252	// mustStoreTally 构造一份内存中的合法计票结果（首次计票路径使用）。
253	// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
254	// validateStoredTally 判定时不会把本进程新建的计票结果误判为字段缺失。
255	func mustStoreTally(forWeight, againstWeight, talliedAt int64) *storedTally {
256		forRaw, _ := json.Marshal(forWeight)
257		againstRaw, _ := json.Marshal(againstWeight)
258		return &storedTally{
259			ForWeight:        forWeight,
260			AgainstWeight:    againstWeight,
261			TalliedAt:        talliedAt,
262			forWeightRaw:     forRaw,
263			againstWeightRaw: againstRaw,
264		}
265	}
