267	// validateStoredTally 严格判定一份已保存计票结果的两个权重字段：
268	// for_weight 与 against_weight 任一未写出、显式为 null 或不是 int64 整数
269	// （字符串/小数/指数/超界）都返回带提案编号、字段名与原因的错误。
270	// 明确写出的 0 是合法权重（该侧没有票），不得当成缺失。
271	// “缺失/空值/类型不符”的判定与逐票明细、执行凭据共用同一份规则
272	// （validateRawFields），此处只补充计票记录的业务位置：提案编号 + tally 标识。
273	func validateStoredTally(id string, t *storedTally) error {
274		return validateRawFields([]rawField{
275			{name: "for_weight", kind: scalarInteger, raw: t.forWeightRaw},
276			{name: "against_weight", kind: scalarInteger, raw: t.againstWeightRaw},
277		}, func(field, problem string) error {
278			return fmt.Errorf("voting proposal %q tally field %q %s", id, field, problem)
279		})
