282	// storedVoteProposal 按成员提交顺序保存成员与委托（顺序不影响相等性），
283	// 动作文本与顺序原样保存（顺序影响相等性）。
284	type storedVoteProposal struct {
285		ID          string             `json:"id"`
286		State       string             `json:"state"`
287		Members     []storedMember     `json:"members"`
288		Delegations []storedDelegation `json:"delegations"`
289		Quorum      int64              `json:"quorum"`
290		StartAt     int64              `json:"start_at"`
291		Deadline    int64              `json:"deadline"`
292		TimelockEnd int64              `json:"timelock_end"`
293		Actions     []string           `json:"actions"`
294		Ballots     []storedBallot     `json:"ballots"`
295		Tally       *storedTally       `json:"tally,omitempty"`
296	}
