532	func voteReject(reason string) error {
533		return fmt.Errorf("%w: %s", ErrVoteRejected, reason)
534	}
535	
536	func tallyReject(reason string) error {
537		return fmt.Errorf("%w: %s", ErrTallyRejected, reason)
538	}
539	
540	// ---- 计票规则（唯一实现，首次计票、打开校验、查询结论共用） ----
541	
542	// ballotCounts 是按逐票明细汇总出的两侧权重。参与量只统计最终代表
543	// 实际投出的票，未投成员的权重既不在 For 也不在 Against 中，
544	// 因而不会被计入 Turnout，更不能直接拿成员总权重充当参与量。
545	type ballotCounts struct {
546		forWeight     int64
547		againstWeight int64
548	}
549	
550	// turnout 返回参与权重（赞成与反对之和），ok 表示合计未溢出 int64。
551	// 两侧各自不超过合法成员总权重时合计必不溢出；此处仍显式检查，
552	// 使“总权重恰好为 math.MaxInt64”的合法提案也不依赖该前提。
553	func (c ballotCounts) turnout() (int64, bool) {
554		return addInt64(c.forWeight, c.againstWeight)
555	}
556	
557	// votePasses 是唯一的通过条件：参与权重达到法定人数（恰好达到也算）
558	// 且赞成严格多于反对。平票、无人投票或参与不足一律不通过。
559	// 通过比较法定人数剩余容量判断参与量，避免 for+against 上溢时回绕为负，
560	// 把已达标（乃至总权重恰好为 int64 上限）的提案误判为参与不足。
561	func votePasses(forWeight, againstWeight, quorum int64) bool {
562		if forWeight <= againstWeight {
563			return false // 平票或赞成更少都不通过；两侧非负，无票时同样落在这里
564		}
565		return forWeight >= quorum-againstWeight // 等价于 for+against >= quorum，且不做上溢加法
566	}
567	
568	// tallyVerdict 把通过条件映射为提案首次计票后的状态。
569	func tallyVerdict(passed bool) string {
570		if passed {
571			return "passed"
572		}
573		return "rejected"
574	}
575	
576	// countBallots 只按票据选择累加两侧权重，不做代表资格与票重核对
577	// （资格核对由 verifyBallots 负责）。任何一侧溢出 int64 都返回损坏错误。
578	func countBallots(ballots []storedBallot) (ballotCounts, error) {
579		var c ballotCounts
580		for _, b := range ballots {
581			if b.Support {
582				sum, ok := addInt64(c.forWeight, b.Weight)
583				if !ok {
584					return ballotCounts{}, errors.New("for-side ballot weights overflow int64")
585				}
586				c.forWeight = sum
587			} else {
588				sum, ok := addInt64(c.againstWeight, b.Weight)
589				if !ok {
590					return ballotCounts{}, errors.New("against-side ballot weights overflow int64")
591				}
592				c.againstWeight = sum
593			}
594		}
595		return c, nil
596	}
597	
598	// verifyBallots 依据成员名单与委托关系逐票核对并汇总：
599	// 代表必须是最终代表、不得重复、票重必须等于委托后归集到其名下的权重。
600	// 这些条件全部由打开状态文件时的严格校验保证，首次计票路径再核对一次，
601	// 使两条路径对“票重/代表是否可信”的判定使用同一份规则。
602	// 汇总只含实际投出的票；任一条件不符返回带具体原因的错误，
603	// 错误分类（ErrStateCorrupt）由调用方按自身路径统一包装。
604	func verifyBallots(id string, ballots []storedBallot, spec *proposalSpec) (ballotCounts, error) {
605		seen := map[string]bool{}
606		for i, b := range ballots {
607			if b.Representative == "" {
608				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d has empty representative", id, i)
609			}
610			if spec.headOf[b.Representative] != b.Representative {
611				return ballotCounts{}, fmt.Errorf("proposal %s ballot %d: %q is not a final representative",
612					id, i, b.Representative)
613			}
614			if seen[b.Representative] {
615				return ballotCounts{}, fmt.Errorf("proposal %s has duplicate stored ballot for %q", id, b.Representative)
616			}
617			seen[b.Representative] = true
618			if b.Weight != spec.groupW[b.Representative] {
619				return ballotCounts{}, fmt.Errorf("proposal %s ballot weight for %q (%d) does not match roster delegation (%d)",
620					id, b.Representative, b.Weight, spec.groupW[b.Representative])
621			}
622		}
623		counts, err := countBallots(ballots)
624		if err != nil {
625			return ballotCounts{}, fmt.Errorf("proposal %s %v", id, err)
626		}
627		return counts, nil
628	}
629	
630	// CastVote 在一项投票提案上投票。调用方通过 now 提供当前时间。
631	// 只有最终代表本人可投赞成/反对票，每位代表一张票，票重为归集到其名下的
632	// 全部原始权重。相同选择的重试始终返回首次记录；改投报冲突。
633	// 首次投票只接受 start <= now < deadline；计票之后拒绝一切新票。
634	func (s *Store) CastVote(id, voter string, support bool, now int64) (*BallotView, error) {
635		if voter == "" {
636			return nil, voteReject("voter id must not be empty")
637		}
638		commit, err := s.begin()
639		if err != nil {
640			return nil, err
641		}
642		defer commit()
643	
644		state, err := s.loadLocked()
645		if err != nil {
646			return nil, err
647		}
648		p, ok := state.VoteProposals[id]
649		if !ok {
650			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
651		}
652		spec, verr := specOf(p)
653		if verr != nil {
654			return nil, verr // 正常路径不会发生：打开与提交前均已严格校验
655		}
656		if _, member := spec.weights[voter]; !member {
657			return nil, voteReject(fmt.Sprintf("voter %q is not on the member roster of %s", voter, id))
658		}
659		if spec.headOf[voter] != voter {
660			return nil, voteReject(fmt.Sprintf("voter %q has delegated the vote to %q and may not vote directly", voter, spec.headOf[voter]))
661		}
662		// 已投过票：相同选择的重试始终返回首次记录（与时间窗口、是否已计票无关）；
663		// 改投另一选择报冲突，绝不静默覆盖。
664		for i := range p.Ballots {
665			if p.Ballots[i].Representative == voter {
666				if p.Ballots[i].Support != support {
667					return nil, fmt.Errorf("%w: representative %q already voted %s for %s; changing the vote is not allowed",
668						ErrProposalConflict, voter, voteChoice(p.Ballots[i].Support), id)
669				}
670				b := p.Ballots[i]
671				return &BallotView{Representative: b.Representative, Weight: b.Weight, Support: b.Support, VotedAt: b.VotedAt}, nil
672			}
673		}
674		if p.Tally != nil {
675			return nil, voteReject(fmt.Sprintf("proposal %s has already been tallied; voting is closed", id))
676		}
677		if now < p.StartAt || now >= p.Deadline {
678			return nil, voteReject(fmt.Sprintf("proposal %s is not open for voting at now=%d (start=%d deadline=%d)", id, now, p.StartAt, p.Deadline))
679		}
680	
681		p.Ballots = append(p.Ballots, mustStoreBallot(voter, spec.groupW[voter], support, now))
682		if err := s.commitLocked(state); err != nil {
683			return nil, err
684		}
685		return &BallotView{Representative: voter, Weight: spec.groupW[voter], Support: support, VotedAt: now}, nil
686	}
687	
688	func voteChoice(support bool) string {
689		if support {
690			return "for"
691		}
692		return "against"
693	}
694	
695	// TallyVote 在截止时刻或之后进行首次计票：赞成与反对权重之和达到法定人数，
696	// 且赞成严格多于反对才通过。未投权重不计入参与量。
697	// 计票只确定状态，不转账；再次计票始终返回首次结论。
698	func (s *Store) TallyVote(id string, now int64) (*TallyResultView, error) {
699		commit, err := s.begin()
700		if err != nil {
701			return nil, err
702		}
703		defer commit()
704	
705		state, err := s.loadLocked()
706		if err != nil {
707			return nil, err
708		}
709		p, ok := state.VoteProposals[id]
710		if !ok {
711			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
712		}
713		if p.Tally != nil {
714			return storedTallyResult(p), nil
715		}
716		if now < p.Deadline {
717			return nil, tallyReject(fmt.Sprintf("voting for %s is still open: now=%d deadline=%d", id, now, p.Deadline))
718		}
719	
720		spec, verr := specOf(p)
721		if verr != nil {
722			return nil, verr
723		}
724		// 计票规则只有一份：同一套“代表资格 + 票重 + 两侧汇总 + 法定人数/多数”
725		// 同时用于首次计票、打开文件时的重放校验与查询结论。
726		counts, verr := verifyBallots(id, p.Ballots, spec)
727		if verr != nil {
728			return nil, fmt.Errorf("%w: %v", ErrStateCorrupt, verr)
729		}
730		passed := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
731		p.Tally = mustStoreTally(counts.forWeight, counts.againstWeight, now)
732		p.State = tallyVerdict(passed)
733		if err := s.commitLocked(state); err != nil {
734			return nil, err
735		}
736		return storedTallyResult(p), nil
737	}
738	
739	// storedTallyResult 从已存储提案重建首次计票结论；尚未计票时返回 nil。
740	// Passed 由唯一的通过规则（votePasses）按保存权重重算：提案后续执行
741	// （executed）不改变首次结论，查询结论与首次计票结论因此始终一致。
742	// 调用方持有的状态均经过 validateState，两侧合计必然不超过合法总权重。
743	func storedTallyResult(p *storedVoteProposal) *TallyResultView {
744		if p.Tally == nil {
745			return nil
746		}
747		c := ballotCounts{forWeight: p.Tally.ForWeight, againstWeight: p.Tally.AgainstWeight}
748		turnout, _ := c.turnout()
749		return &TallyResultView{
750			ForWeight:     c.forWeight,
751			AgainstWeight: c.againstWeight,
752			Turnout:       turnout,
753			Quorum:        p.Quorum,
754			Passed:        votePasses(c.forWeight, c.againstWeight, p.Quorum),
755			TalliedAt:     p.Tally.TalliedAt,
756		}
757	}
758	
759	// VoteProposal 按编号查询一项投票提案；不存在时 ok 为 false。
760	func (s *Store) VoteProposal(id string) (*VoteProposalView, bool, error) {
761		state, err := s.readState()
762		if err != nil {
763			return nil, false, err
764		}
765		p, ok := state.VoteProposals[id]
766		if !ok {
767			return nil, false, nil
768		}
769		return voteProposalView(p), true, nil
770	}
771	
772	// VoteProposals 返回全部投票提案，按编号排序。
773	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
774		state, err := s.readState()
775		if err != nil {
776			return nil, err
777		}
778		return voteProposalViews(state), nil
779	}
780	
781	func voteProposalViews(state *storedState) []*VoteProposalView {
782		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
783		for _, p := range state.VoteProposals {
784			out = append(out, voteProposalView(p))
785		}
786		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
787		return out
788	}
789	
790	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
791		spec, err := specOf(p)
792		if err != nil {
793			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
794			panic("govflow: building view of corrupt proposal: " + err.Error())
795		}
796		members := make([]MemberView, 0, len(p.Members))
797		for _, m := range p.Members { // 保持成员提交顺序
798			mv := MemberView{
799				ID:       m.ID,
800				Weight:   m.Weight,
801				Path:     append([]string(nil), spec.pathOf[m.ID]...),
802				Delegate: spec.headOf[m.ID],
803			}
804			if to, ok := spec.delegate[m.ID]; ok {
805				mv.Direct = to
806			}
807			members = append(members, mv)
808		}
809		ballots := make([]BallotView, 0, len(p.Ballots))
810		for _, b := range p.Ballots { // 保持首次投票先后顺序
811			ballots = append(ballots, BallotView{
812				Representative: b.Representative,
813				Weight:         b.Weight,
814				Support:        b.Support,
815				VotedAt:        b.VotedAt,
816			})
817		}
818		v := &VoteProposalView{
819			ID:          p.ID,
820			Source:      "vote",
821			State:       p.State,
822			Quorum:      p.Quorum,
823			StartAt:     p.StartAt,
824			Deadline:    p.Deadline,
825			TimelockEnd: p.TimelockEnd,
826			Actions:     copyActions(p.Actions),
827			TotalWeight: spec.total,
828			Members:     members,
829			Ballots:     ballots,
830		}
831		if p.Tally != nil {
832			v.Tally = storedTallyResult(p)
833		}
834		return v
835	}
836	
837	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
838	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
839		in := &CreateVoteInput{
840			ID:          p.ID,
841			Quorum:      p.Quorum,
842			StartAt:     p.StartAt,
843			Deadline:    p.Deadline,
844			TimelockEnd: p.TimelockEnd,
845			Actions:     p.Actions,
846		}
847		in.Members = make([]VoteMember, len(p.Members))
848		for i, m := range p.Members {
849			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
850		}
851		in.Delegations = make([]Delegation, len(p.Delegations))
852		for i, d := range p.Delegations {
853			in.Delegations[i] = Delegation{From: d.From, To: d.To}
854		}
855		return validateProposalInput(in)
856	}
857	
858	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
859	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
860	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
861	func validateVoteProposals(state *storedState) error {
862		for key, p := range state.VoteProposals {
863			if p == nil {
864				return fmt.Errorf("voting proposal %q is empty", key)
865			}
866			if p.ID != key || p.ID == "" {
867				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
868			}
869			if _, collide := state.Proposals[p.ID]; collide {
870				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
871			}
872			switch p.State {
873			case "voting", "passed", "rejected", "executed":
874			default:
875				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
876			}
877			spec, err := specOf(p)
878			if err != nil {
879				return err
880			}
881	
882			// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
883			// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
884			// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
885			// 默认成 0 后再继续给出查询或计票的部分结果。
886			for i := range p.Ballots {
887				if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
888					return err
889				}
890			}
891	
892			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
893			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
894			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
895			counts, err := verifyBallots(p.ID, p.Ballots, spec)
896			if err != nil {
897				return err
898			}
899			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
900			// 仍只属于打开时的明细校验。
901			for _, b := range p.Ballots {
902				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
903					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
904						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
905				}
906			}
907	
908			switch {
909			case p.Tally == nil:
910				if p.State != "voting" {
911					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
912				}
913			default:
914				if p.State == "voting" {
915					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
916				}
917				// 只要提案有计票结果，for_weight 与 against_weight 就必须各自明确
918				// 写出且为 int64 整数。先于权重重放核对执行：字段缺损时直接判整份
919				// 文件损坏，绝不能把缺失的一侧默认补成 0（恰好等于该侧真实零票重）
920				// 后再继续给出查询或再次计票的结果。明确写出的 0 是合法权重。
921				if err := validateStoredTally(p.ID, p.Tally); err != nil {
922					return err
923				}
924				if p.Tally.TalliedAt < p.Deadline {
925					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
926				}
927				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
928					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
929						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
930				}
931				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
932				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
933				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
934				if passedNow != (p.State == "passed" || p.State == "executed") {
935					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
936				}
937			}
938		}
939		return nil
940	}
941

