		// 合法转义拼写与普通拼写是同一个键：balances 中同时写出
		// "audit" 与 "audit" 仍按重复键拒绝，而不是被文本校验放行。
		raw := strings.Replace(string(stringTextBaseState), `"balances": {}`,
